float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=6;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader amzt_d1;
float4 amzSample_d1(float2 uv) { return float4(amzt_d1.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0)); }
uniform shader amzt_d2;
float4 amzSample_d2(float2 uv) { return float4(amzt_d2.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/4.0)); }
uniform shader amzt_d3;
float4 amzSample_d3(float2 uv) { return float4(amzt_d3.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/8.0)); }
uniform shader amzt_d4;
float4 amzSample_d4(float2 uv) { return float4(amzt_d4.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/16.0)); }
uniform shader amzt_d5;
float4 amzSample_d5(float2 uv) { return float4(amzt_d5.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/32.0)); }
uniform shader amzt_d6;
float4 amzSample_d6(float2 uv) { return float4(amzt_d6.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/64.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_d1(uv);if(tex==2) return amzSample_d2(uv);if(tex==3) return amzSample_d3(uv);if(tex==4) return amzSample_d4(uv);if(tex==5) return amzSample_d5(uv);if(tex==6) return amzSample_d6(uv);return float4(0.0); }
uniform float amzp_radius;
uniform float amzp_exposure;
uniform float amzp_threshold;
uniform float amzp_thresholdSmooth;
uniform float amzp_satBias;
uniform float amzp_falloff;
uniform float amzp_tailWeight;
uniform float amzp_radiusExpand;
uniform float amzp_stretchX;
uniform float amzp_stretchY;
uniform float amzp_radiusR;
uniform float amzp_radiusG;
uniform float amzp_radiusB;
uniform float amzp_caAmount;
uniform float amzp_caMode;
uniform float amzp_caAngle;
uniform float amzp_caFeather;
uniform float amzp_tintMode;
layout(color) uniform half4 amzp_tintColor;
layout(color) uniform half4 amzp_tintInner;
layout(color) uniform half4 amzp_tintOuter;
uniform float amzp_tintAmount;
uniform float amzp_saturation;
uniform float amzp_tonemap;
uniform float amzp_glowBlend;
uniform float amzp_glowOnly;
uniform float amzp_dither;
uniform float amzp_linearWf;
uniform float amzp_glowOpacity;
uniform float amzp_sourceOpacity;
uniform float amzp_shadowOn;
layout(color) uniform half4 amzp_shadowColor;
uniform float amzp_shadowRadius;
uniform float amzp_shadowAlpha;
uniform float amzp_shadowDist;
uniform float amzp_shadowAngle;
uniform float amzp_overdrawOn;
    float3 toLin(float3 c) { return (amzp_linearWf>0.5) ? pow(max(c, 0.0), float3(2.2)) : c; }
    float3 toGam(float3 c) { return (amzp_linearWf>0.5) ? pow(max(c, 0.0), float3(1.0 / 2.2)) : c; }
    float3 thresholded(float4 c) {
        if (c.a <= 0.0001) return float3(0.0);
        float3 u = c.rgb / c.a;
        float mn = min(u.r, min(u.g, u.b));
        float3 v = u + clamp(amzp_satBias, 0.0, 1.0) * (u - mn);
        float t = clamp(amzp_threshold, 0.0, 1.0);
        float k = 0.004 + clamp(amzp_thresholdSmooth, 0.0, 1.0) * 0.12;
        float3 m = smoothstep(float3(t - k), float3(t + k), v);
        if (t <= 0.0) m = float3(1.0);
        return toLin(u * m) * c.a;
    }
    float2 caOff(float2 uv) {
        float ca = max(amzp_caAmount, 0.0);
        float pxs = screen.zw.x / max(screen.zw.x, 1.0);
        if (int(amzp_caMode) == 0) {
            float2 cc = (float4(0.5, 0.5, 0.0, 1.0) * amzLayerToScreen()).xy;
            return (uv - cc) * (-0.05 * ca);
        }
        float an = radians(-amzp_caAngle);
        return float2(cos(an), sin(an)) * 24.0 * ca * pxs / screen.zw;
    }
    float3 thrAt(float2 uv) { return thresholded(amzTexture(0, uv)); }
    float3 splitSrc(float2 uv) {
        if (max(amzp_caAmount, 0.0) <= 0.0001) return thrAt(uv);
        float2 ro = caOff(uv);
        float fe = clamp(amzp_caFeather, 0.0, 1.0);
        if (fe <= 0.001) return float3(thrAt(uv + ro).r, thrAt(uv).g, thrAt(uv - ro).b);
        float sg = 0.3 + fe * 1.4;
        float3 acc = float3(0.0), ws = float3(0.0);
        for (int k = 0; k < 7; k++) {
            float tt = float(k) / 3.0 - 1.0;
            float3 d = (float3(tt) - float3(1.0, 0.0, -1.0)) / sg;
            float3 w = exp(-d * d);
            acc += thrAt(uv + ro * tt) * w;
            ws += w;
        }
        return acc / max(ws, float3(1e-4));
    }
    float2 stretchV() { return float2(clamp(amzp_stretchX, 0.1, 4.0), clamp(amzp_stretchY, 0.1, 4.0)); }
    float4 rd(int t, float2 uv) { float4 c = amzTexture(t, uv); return float4(c.rgb * c.rgb, c.a); }
    float4 wr(float4 v) { return float4(sqrt(clamp(v.rgb, 0.0, 1.0)), clamp(v.a, 0.0, 1.0)); }
    float4 down13(int t, float2 ts, float2 uv) {
        float2 o = ts * stretchV();
        float4 a = rd(t, uv + o * float2(-2.0, 2.0));
        float4 b = rd(t, uv + o * float2(0.0, 2.0));
        float4 c = rd(t, uv + o * float2(2.0, 2.0));
        float4 d = rd(t, uv + o * float2(-2.0, 0.0));
        float4 e = rd(t, uv);
        float4 f = rd(t, uv + o * float2(2.0, 0.0));
        float4 g = rd(t, uv + o * float2(-2.0, -2.0));
        float4 h = rd(t, uv + o * float2(0.0, -2.0));
        float4 i = rd(t, uv + o * float2(2.0, -2.0));
        float4 j = rd(t, uv + o * float2(-1.0, 1.0));
        float4 k = rd(t, uv + o * float2(1.0, 1.0));
        float4 l = rd(t, uv + o * float2(-1.0, -1.0));
        float4 m = rd(t, uv + o * float2(1.0, -1.0));
        return e * 0.125 + (a + c + g + i) * 0.03125 + (b + d + f + h) * 0.0625 + (j + k + l + m) * 0.125;
    }
    float4 up9(int t, float2 ts, float2 uv) {
        float2 o = ts * stretchV();
        float4 s = rd(t, uv) * 4.0;
        s += (rd(t, uv + o * float2(1.0, 0.0)) + rd(t, uv - o * float2(1.0, 0.0))
            + rd(t, uv + o * float2(0.0, 1.0)) + rd(t, uv - o * float2(0.0, 1.0))) * 2.0;
        s += rd(t, uv + o) + rd(t, uv - o) + rd(t, uv + o * float2(1.0, -1.0)) + rd(t, uv + o * float2(-1.0, 1.0));
        return s / 16.0;
    }
    float3 wLevel(float k, float3 r) {
        if (k < 0.5) return float3(1.0);
        float s = pow(2.0, k) * 1.6;
        float ex = mix(1.0, max(amzp_radiusExpand, 0.05), clamp((k - 1.0) / 5.0, 0.0, 1.0));
        float3 q = s / max(r * ex, float3(1e-3));
        float3 cut = 1.0 / (1.0 + q * q * q * q);
        return cut * pow(2.0, -k * amzp_falloff * 1.2) * pow(max(amzp_tailWeight, 0.0), clamp((k - 1.0) / 4.0, 0.0, 2.0));
    }
    float3 tm(float3 x) {
        if (int(amzp_tonemap) == 1) return x / (1.0 + max(x - 1.0, 0.0));
        if (int(amzp_tonemap) == 2) return x / (1.0 + x);
        if (int(amzp_tonemap) == 3) { float3 a = x * 0.6; return clamp((a * (2.51 * a + 0.03)) / (a * (2.43 * a + 0.59) + 0.14), 0.0, 1.0); }
        if (int(amzp_tonemap) == 4) {
            float3 A = x * 2.0;
            float3 h = ((A * (0.15 * A + 0.05) + 0.004) / (A * (0.15 * A + 0.5) + 0.06)) - 0.0667;
            return h / 0.7215;
        }
        if (int(amzp_tonemap) == 5) { float m = max(x.r, max(x.g, x.b)); return m > 0.8 ? x * (0.8 + (1.0 - 0.8) * (1.0 - exp(-(m - 0.8) / 0.2))) / m : x; }
