        float shL = shLevel();
        sh = 0.0;
        if ((amzp_shadowOn>0.5) && shL < 1.0) sh = amzTexture(0, uv - shOff()).a * (1.0 - shL);
        float3 w1 = wLevel(1.0, r), w2 = wLevel(2.0, r), w3 = wLevel(3.0, r), w4 = wLevel(4.0, r), w5 = wLevel(5.0, r);
        float3 w6 = wLevel(6.0, r), w7 = wLevel(7.0, r), w8 = wLevel(8.0, r), w9 = wLevel(9.0, r);
        float3 wsum = float3(1.0) + w1 + w2 + w3 + w4 + w5 + w6 + w7 + w8 + w9;
        float3 acc = doG ? tinted(splitSrc(uv), 0.0) : float3(0.0);
