    }
    void nmMain() {
        float2 uv = amzScreenNorm();
        if (amzPass == 0) {
            float2 o = 0.5 / screen.zw;
            float3 c = float3(0.0);
            if (amzp_exposure > 0.0) c = splitSrc(uv + float2(-o.x, -o.y)) + splitSrc(uv + float2(o.x, -o.y)) + splitSrc(uv + float2(-o.x, o.y)) + splitSrc(uv + float2(o.x, o.y));
