            amzOutput = wr(down13(3, 1.0 / (screen.zw/8.0), uv));
        } else if (amzPass == 4) {
            amzOutput = wr(down13(4, 1.0 / (screen.zw/16.0), uv));
        } else if (amzPass == 5) {
            amzOutput = wr(down13(5, 1.0 / (screen.zw/32.0), uv));
