            float4 base = amzTexture(0, uv);
            float pxs = screen.zw.x / max(screen.zw.x, 1.0);
            float3 r = max(amzp_radius, 0.0) * pxs * float3(amzp_radiusR, amzp_radiusG, amzp_radiusB);
