            float3 srcLin = base.a > 0.0001 ? toLin(base.rgb / base.a) * base.a * sa : float3(0.0);
            float3 sum;
            if (int(amzp_glowBlend) == 0 || (amzp_glowOnly>0.5)) {
                sum = tm(srcLin + glow);
            } else {
                float3 gt = clamp(tm(glow), 0.0, 1.0);
                float3 s0 = clamp(srcLin, 0.0, 1.0);
                sum = int(amzp_glowBlend) == 1 ? s0 + gt - s0 * gt : max(s0, gt);
            }
            float3 P = clamp(toGam(sum), 0.0, 1.0);
            float dz = max(amzp_dither, 0.0);
            if (dz > 0.0) {
                float2 ip = floor(uv * screen.zw);
                float n = fract(sin(dot(ip, float2(12.9898, 78.233))) * 43758.5453) + fract(sin(dot(ip, float2(39.3468, 11.1353))) * 24634.6345) - 1.0;
                float gm = max(glow.r, max(glow.g, glow.b));
                P = clamp(P + n * dz * smoothstep(0.0, 0.02, gm), 0.0, 1.0);
            }
            float a = clamp(max(base.a * sa, max(P.r, max(P.g, P.b))), 0.0, 1.0);
            float4 res = a <= 0.0001 ? float4(0.0) : float4(min(P, float3(a)), a);
            float4 org = (amzp_glowOnly>0.5) ? float4(0.0) : base * sa;
            float4 outc = mix(org, res, smoothstep(0.0, 0.05, ex));
            if ((amzp_shadowOn>0.5)) {
                float sA = clamp(shA * clamp(amzp_shadowAlpha, 0.0, 3.0), 0.0, 1.0);
                outc += float4(amzp_shadowColor.rgb * sA, sA) * (1.0 - outc.a);
            }
            amzOutput = outc;
        }
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5) && amzPass >= 6) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

