    float2 stretchV() { return float2(clamp(amzp_stretchX, 0.1, 4.0), clamp(amzp_stretchY, 0.1, 4.0)); }
    float4 rd(int t, float2 uv) { float4 c = amzTexture(t, uv); return float4(c.rgb * c.rgb, c.a); }
