        float4 d = rd(t, uv + o * float2(-2.0, 0.0));
        float4 e = rd(t, uv);
        float4 f = rd(t, uv + o * float2(2.0, 0.0));
        float4 g = rd(t, uv + o * float2(-2.0, -2.0));
