        level(1, 1.0 / (screen.zw/2.0), uv, 1.0, kn, w1, doG, shL, acc, sh);
        level(2, 1.0 / (screen.zw/4.0), uv, 2.0, kn, w2, doG, shL, acc, sh);
        level(3, 1.0 / (screen.zw/8.0), uv, 3.0, kn, w3, doG, shL, acc, sh);
        level(4, 1.0 / (screen.zw/16.0), uv, 4.0, kn, w4, doG, shL, acc, sh);
        level(5, 1.0 / (screen.zw/32.0), uv, 5.0, kn, w5, doG, shL, acc, sh);
        level(6, 1.0 / (screen.zw/64.0), uv, 6.0, kn, w6, doG, shL, acc, sh);
        level(6, 2.0 / (screen.zw/64.0), uv, 7.0, kn, w7, doG, shL, acc, sh);
        level(6, 4.0 / (screen.zw/64.0), uv, 8.0, kn, w8, doG, shL, acc, sh);
        level(6, 8.0 / (screen.zw/64.0), uv, 9.0, kn, w9, doG, shL, acc, sh);
